 const rect = this.canvas.getBoundingClientRect();
 const aspect = rect.width/rect.height;
 let w = aspect < 0.9 ? 700 : aspect < 1.35 ? 1000 : 1280;
 const h = w/aspect;
 this.world = {w,h,ground: h*(aspect<0.9?0.67: aspect<1.35?0.78:0.82), aspect};
 this.canvas.width = Math.round(rect.width*dpr);
 this.canvas.height=...
 this.ctx.setTransform(this.canvas.width/w, 0,0, this.canvas.height/h,0,0);
 // reposition fighters if in title
 if (this.state==='title') this.placeTitleFighters()
 else { clamp x to bounds }
}
```
But ctx transform set once; render clears with identity? We can use `ctx.setTransform(scaleX,0,0,scaleY,0,0)` each render. `ctx.clearRect(0,0,w,h)`. Note canvas width = rect.width*dpr, scaleX = canvas.width/w.

