}

.meter {
  position: relative;
  height: 14px;
  margin-top: 6px;
}

.meter::before {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  bottom: 5px;
  height: 1px;
  background: rgba(244, 241, 232, 0.14);
}

.meter i {
  position: absolute;
  left: 0;
  bottom: 4px;
  height: 2px;
  width: 100%;
  background: var(--red);
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 0.1s linear;
}

.rival .meter i {
  left: auto;
  right: 0;
  transform-origin: right center;
}

.meter-label {
  position: absolute;
  right: 0;
  bottom: -4px;
  font: 500 7px/1 var(--mono);
  letter-spacing: 0.24em;
  color: rgba(244, 241, 232, 0.34);
  transition: color 0.2s ease;
