}

.meter.ready .meter-label {
  color: var(--red);
}

.meter.active i {
  background: var(--red);
  box-shadow: 0 0 14px rgba(255, 59, 48, 0.9);
}

.meter.active .meter-label {
  color: var(--red);
}

@keyframes meterPulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.45;
  }
}

.hud-center {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  padding-top: 1px;
}

#round-label {
  font: 500 8px/1 var(--mono);
  letter-spacing: 0.3em;
  color: rgba(244, 241, 232, 0.4);
  white-space: nowrap;
}

.vs {
  font: 400 20px/0.9 var(--display);
  letter-spacing: 0.04em;
  color: rgba(244, 241, 232, 0.8);
}

#mute {
  margin-top: 6px;
  padding: 5px 7px;
  border: 1px solid rgba(244, 241, 232, 0.14);
