  }
}

@media (prefers-reduced-motion: reduce) {
  .banner.show .banner-main,
  .banner.show .banner-sub,
  .meter.ready i,
  .tbtn.power.ready {
    animation: none;
  }
}

content.text:
Now main.js.

Need handle UI and input.

Elements:
```
const $ = (id)=>document.getElementById(id)
```

Input class:
```
class Input {
 constructor(){
   this.held = {left:false,right:false,guard:false};
   this.edges = {jump:false,strike:false,heavy:false,power:false,dash:0};
   this.lastDirTap = 0; this.lastDir = 0;
   window.addEventListener('keydown', e=>this.onKey(e,true));
   window.addEventListener('keyup', ...);
 }
 onKey(e, down){
   const k = e.key.toLowerCase();
   if (['arrowleft','arrowright','arrowup',' ','spacebar'].includes(k) ...) e.preventDefault();
   if (e.repeat) { if (down) return; }
   switch...
 }
 control(){
   const c = {move: (held.right?1:0)-(held.left?1:0), guard: held.guard, jump: edges.jump, strike:..., dash: edges.dash};
   this.edges={...}; return c;
 }
}
```
Careful: For guard, held.guard true while L pressed. On keyup false.

Keys:
- ArrowLeft, a → held.left.
- ArrowRight, d → held.right.
- ArrowUp, w, space → edge jump (on keydown).
- j → strike.
- k → heavy.
- l → guard held.
- q → power.
- shift → dash (direction based on held).
- Enter/Space start/rematch? Space is jump during fight, so title handler separate. In main keydown global for Enter/R/M. We can let Input handle start callback.
- Escape? maybe pause not implemented.
- r on result → rematch.
- m → mute.

Prevent default for space, arrows, shift maybe.

Touch joystick:
```
const stick = $('#stick'), knob = $('#knob');
let stickId=null, center...
stick.addEventListener('pointerdown', e=>{ stickId=e.pointerId; stick.setPointerCapture; stick.classList.add('active'); updateStick(e);});
pointermove if id; updateStick
pointerup/cancel reset.
function updateStick(e){
  const rect=stick.getBoundingClientRect(); const cx=rect.left+rect.width/2; ...
  let dx=e.clientX-cx, dy=e.clientY-cy; const max=rect.width*0.32; 
  const dist=Math.hypot(dx,dy); if(dist>max){dx=dx/dist*max;dy=...}
  knob.style.transform=`translate(${dx}px,${dy}px)`;
  const nx=dx/max;
  input.held.left = nx < -0.28; input.held.right = nx > 0.28;
  // double tap dash
  const dir = nx>0.55?1:nx<-0.55?-1:0;
  if (dir && dir !== input.lastJoyDir) { const now=performance.now(); if (now-input.lastTap<300 && dir===input.lastTapDir) input.edges.dash=dir; input.lastTap=now; input.lastTapDir=dir; }
  input.lastJoyDir=dir;
}
```
Need to not override keyboard held when stick released? If both, okay. But when releasing stick set held left/right false, could cancel keyboard held. Rare. Fine.

Double-tap: direction change and same as last tap within 300ms triggers dash. But if user flicks right (dir 1), then releases (dir 0), then flicks right again within 300ms → triggers. Good. Need update lastJoyDir on release 0.

Buttons:
```
document.querySelectorAll('.tbtn').forEach(btn=>{
 const act=btn.dataset.act;
 btn.addEventListener('pointerdown', e=>{e.preventDefault(); btn.setPointerCapture(e.pointerId); btn.classList.add('pressed'); if(act==='guard') input.held.guard=true; else if(act==='dash')... else input.edges[act]=true; if(act==='power') game.sfx.unlock();});
 const release=... remove pressed; if guard false;
 pointerup, pointercancel, lostpointercapture
});
```
For power, should only activate when ready but fighter handles.

Potential issue: `pointerup` on button after setPointerCapture. Good.

Touch power button gets class ready/active synced each frame.

UI functions:
```
function showHud(show){ hud.classList.toggle('hidden', !show); }
function startGame(){
  if (game.state!=='title' && game.state!=='matchover') return;
  game.sfx.unlock();
  title.classList.add('hidden');
  result.classList.add('hidden');
  result.classList.remove('defeat');
  hud.classList.remove('hidden');
  document.body.classList.add('in-match');
  game.startMatch();
  // focus stage? no
}
```
On matchover, result callback shows overlay, hide hud? Keep HUD dim behind. Body class still in-match so touch controls visible behind result overlay (z20 < result z30) but result overlay covers with background. Touch controls might still receive pointer? Result overlay is above and covers; z30. Fine. But set body class remove on result to hide touch.

`showResult(data)`:
```
document.body.classList.remove('in-match');
