input.newString:
const STEP = 1 / 60;
let last = performance.now();
let accumulator = 0;

function frame(now) {
  const elapsed = Math.min((now - last) / 1000, 0.12);
  last = now;
  accumulator += elapsed;

  let steps = 0;
  while (accumulator >= STEP && steps < 7) {
    if (game.state === 'fight') {
      game.playerControl = input.control();
    } else {
      input.control();
      game.playerControl = game.player.emptyControl();
    }
    game.update(STEP);
    accumulator -= STEP;
    steps += 1;
  }
  if (steps === 7) accumulator = 0;

  game.render();
  syncHud();

  requestAnimationFrame(frame);
}

requestAnimationFrame((now) => {
  last = now;
  requestAnimationFrame(frame);
});

