page.on('pageerror', e=>console.log('ERR',e.message));
await page.goto('http://localhost:3002');
await page.click('#start');
const read = () => page.evaluate(() => {
  const g=window.__POWER__.game; const p=g.player, e=g.enemy;
  return { state:g.state, round:g.round, scores:{...g.scores}, time:+g.stats.time.toFixed(1), p:{x:p.x,hp:p.hp,power:p.power,atk:p.attack?.type,atk_t:p.attack?.t,block:p.blocking,stun:p.stun,hit:p.hitstun,dir:p.facing}, e:{x:e.x,hp:e.hp,power:e.power,atk:e.attack?.type,atk_t:e.attack?.t,startup:e.attack?.def.startup,block:e.blocking,stun:e.stun,hit:e.hitstun,dir:e.facing} };
});
let guarding=false;
for (let step=0; step<1200; step++) {
  const s=await read();
  if (s.state==='matchover') { console.log('MATCHOVER', s.scores, 'time', s.time); break; }
  if (s.state!=='fight') { await page.waitForTimeout(120); continue; }
  const dist=Math.abs(s.e.x-s.p.x);
  const toward=s.e.x>s.p.x?'d':'a';
  // defend incoming
  const incoming = s.e.atk && s.e.atk_t < s.e.startup + 0.02;
  if (incoming && dist < 170 && !guarding) {
    await page.keyboard.down('l'); guarding=true;
    await page.waitForTimeout(120);
    await page.keyboard.up('l'); guarding=false;
    continue;
  }
  if (s.p.power>=100 && dist<170) { await page.keyboard.press('q'); await page.waitForTimeout(60); }
  if (dist>115) {
    await page.keyboard.down(toward); await page.waitForTimeout(60); await page.keyboard.up(toward);
  } else {
    if (Math.random()<0.25) await page.keyboard.press('k'); else await page.keyboard.press('j');
    await page.waitForTimeout(70);
  }
  await page.waitForTimeout(45);
}
const final=await read();
console.log('FINAL', JSON.stringify(final));
await page.screenshot({ path:'/tmp/opencode/botfight.png' });
