  g.enemy.startAttack('light', g);
  g.enemy.attack.t = g.enemy.attack.def.startup;
  out.parryReturn = g.resolveHit(g.enemy, g.player);
  out.parry = { playerPower: g.player.power, enemyStun: g.enemy.stun, playerHp: g.player.hp };
  // reset for block
  g.enemy.stun=0; g.enemy.attack=null; g.enemy.startAttack('light', g); g.enemy.attack.t=g.enemy.attack.def.startup;
  g.player.blockTime=0.5; g.player.blocking=true;
  out.blockReturn = g.resolveHit(g.enemy, g.player);
  out.block = { playerHp: g.player.hp, playerPower: g.player.power };
  // reset for hit
  g.enemy.attack=null; g.enemy.startAttack('heavy', g); g.enemy.attack.t=g.enemy.attack.def.startup;
  g.player.blocking=false; g.player.blockTime=0;
  out.hitReturn = g.resolveHit(g.enemy, g.player);
  out.hit = { playerHp: g.player.hp, playerHitstun:+g.player.hitstun.toFixed(2), playerVx:+g.player.vx.toFixed(0), enemyPower:g.enemy.power };
