import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = '/tmp/opencode/playtest';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', (e) => { console.log('PAGEERROR', e.message); errors.push(e.message); });
page.on('console', (m) => { if (m.type() === 'error') { console.log('CONSOLE', m.text()); errors.push(m.text()); } });
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.click('#start');
await page.waitForTimeout(1800);
const state = async () => page.evaluate(() => {
  const g = window.__POWER__.game;
  return { state: g.state, round: g.round, scores: g.scores, p: { x: Math.round(g.player.x), hp: g.player.hp, power: Math.round(g.player.power), state: g.player.attack?.type || (g.player.blocking?'block':'idle'), pwr: +g.player.powerTime.toFixed(1) }, e: { x: Math.round(g.enemy.x), hp: g.enemy.hp, power: Math.round(g.enemy.power), state: g.enemy.attack?.type || (g.enemy.blocking?'block':'idle') } };
});
console.log('t0', await state());
await page.screenshot({ path: `${out}/01-start.png` });
// approach and throw hands
await page.keyboard.down('d');
await page.waitForTimeout(500);
await page.keyboard.up('d');
await page.keyboard.press('j');
await page.waitForTimeout(140);
await page.screenshot({ path: `${out}/02-jab.png` });
console.log('jab', await state());
await page.keyboard.press('j');
await page.waitForTimeout(90);
await page.keyboard.press('j');
await page.waitForTimeout(400);
await page.screenshot({ path: `${out}/03-combo.png` });
console.log('combo', await state());
// heavy
await page.keyboard.press('k');
await page.waitForTimeout(300);
await page.screenshot({ path: `${out}/04-heavy.png` });
console.log('heavy', await state());
// guard
await page.keyboard.down('l');
await page.waitForTimeout(700);
await page.screenshot({ path: `${out}/05-guard.png` });
await page.keyboard.up('l');
console.log('guard', await state());
// fight for a while, spam to see KO eventually
for (let i = 0; i < 22; i++) {
  const s = await state();
  if (s.state === 'matchover') break;
  const dx = s.e.x - s.p.x;
  if (Math.abs(dx) > 130) {
    if (dx > 0) { await page.keyboard.down('d'); await page.waitForTimeout(90); await page.keyboard.up('d'); }
    else { await page.keyboard.down('a'); await page.waitForTimeout(90); await page.keyboard.up('a'); }
  } else {
    if (i % 4 === 0) await page.keyboard.press('k'); else await page.keyboard.press('j');
  }

